"""Hardware-only AV1 through the pinned private pixelflux 2.2.3 runtime."""
import struct
import threading

from .hevc_capture import runtime

FIRST_FRAME_TIMEOUT = 8
MAX_PENDING_FRAMES = 120
MAX_PACKET_BYTES = 16 * 1024 * 1024
MAX_PENDING_BYTES = 32 * 1024 * 1024
MAX_DIMENSION = 8192


def available():
    """Whether the private runtime exposes the required API, not GPU support."""
    try:
        module = runtime()
        return all(callable(getattr(module, name, None)) for name in (
            "ScreenCapture", "CaptureSettings", "hardware_encoders", "hardware_formats"))
    except (ImportError, OSError, RuntimeError):
        return False


def packet(native, width, height):
    """Convert the native 12-byte video header to the existing geometry/ACK wire.

    Source dimensions stay authoritative: an encoder may pad its coded picture,
    but that must not resize the desktop or its input coordinate space.
    """
    if len(native) <= 12:
        raise RuntimeError("AV1 encoder returned a truncated frame")
    if len(native) > MAX_PACKET_BYTES:
        raise RuntimeError("AV1 encoder returned an oversized frame")
    tag, kind, frame_id, y, coded_w, coded_h, _reference = struct.unpack("!BBHHHHH", native[:12])
    frame_kind = kind & 7  # The native anchor flag (0x08) is not a key frame.
    if tag != 4 or kind >> 4 != 4 or frame_kind not in (0, 1, 2):
        raise RuntimeError("AV1 encoder returned an unexpected codec or frame type")
    if (y != 0 or not 0 < width <= MAX_DIMENSION or not 0 < height <= MAX_DIMENSION
            or not width <= coded_w < width + 128
            or not height <= coded_h < height + 128):
        raise RuntimeError("AV1 encoder returned incompatible frame geometry")
    header = struct.pack("!BBHHHH", 6, int(frame_kind == 1), frame_id, 0, width, height)
    return header + native[12:], frame_id


class Av1Capture:
    def __init__(self):
        self.capture = runtime().ScreenCapture()
        self._lock = threading.Lock()
        self._error = None
        self._stopped = False

    def _validate_info(self, info):
        if (not info or str(info.get("codec")).lower() != "av1"
                or info.get("hardware") is not True
                or info.get("bit_depth") != 8 or info.get("fullcolor") is not False
                or info.get("striped") is not False):
            reason = (info or {}).get("encoder_reason") or "unexpected codec, hardware or pixel format"
            raise RuntimeError("AV1 hardware encoding unavailable: " + str(reason))
        return info

    def check_health(self):
        """Also called by the server after startup to catch runtime demotion."""
        with self._lock:
            if self._error is not None:
                raise self._error
            if self._stopped:
                raise RuntimeError("AV1 capture stopped")
        try:
            return self._validate_info(self.capture.stream_info())
        except Exception as exc:
            with self._lock:
                self._error = RuntimeError("AV1 hardware health check failed: " + str(exc))
            raise self._error from exc

    def start_capture(self, legacy, callback):
        module = runtime()
        if legacy.use_cpu:
            raise RuntimeError("AV1 requires GPU encoding; CPU mode is enabled or locked")
        if (legacy.scale != 1 or legacy.auto_adjust_screen_capture_size
                or not 0 < legacy.capture_width <= MAX_DIMENSION
                or not 0 < legacy.capture_height <= MAX_DIMENSION):
            raise RuntimeError("AV1 requires fixed full-frame capture geometry")
        node = legacy.vaapi_render_node_index
        if node < 0 or "av1" not in module.hardware_encoders(node):
            raise RuntimeError("Selected GPU has no AV1 encoder; using H.264")
        if "420-8" not in module.hardware_formats(node).get("av1", ()):
            raise RuntimeError("Selected GPU has no AV1 8-bit 4:2:0 encoder")

        settings = module.CaptureSettings()
        for name in ("capture_width", "capture_height", "capture_x", "capture_y", "capture_cursor",
                     "target_fps", "scale", "auto_adjust_screen_capture_size",
                     "use_paint_over_quality", "paint_over_trigger_frames", "damage_block_threshold",
                     "damage_block_duration", "watermark_location_enum"):
            setattr(settings, name, getattr(legacy, name))
        watermark = legacy.watermark_path
        settings.watermark_path = watermark.decode("utf-8") if isinstance(watermark, bytes) else watermark
        for name in ("crf", "paintover_crf", "paintover_burst_frames", "streaming_mode"):
            setattr(settings, "video_" + name, getattr(legacy, "h264_" + name))
        settings.codec = "av1"
        settings.use_cpu = False
        settings.use_wayland = False
        settings.video_fullframe = True
        settings.video_fullcolor = False
        settings.video_bit_depth = 8
        # StripeFrame has no keyframe attribute. Keep the upstream header for
        # its codec and frame-kind fields, then adapt it to our existing wire.
        settings.omit_stripe_headers = False
        settings.encode_node_index = node
        accepted = False
        have_keyframe = False
        pending = []
        pending_bytes = 0
        first_frame = threading.Event()

        def deliver(frame):
            nonlocal have_keyframe, pending_bytes
            # Native callback exceptions may be swallowed by the capture
            # thread. Retain them for startup and the server's health monitor.
            with self._lock:
                if self._stopped or self._error is not None:
                    return
                try:
                    data, frame_id = packet(bytes(frame), settings.capture_width, settings.capture_height)
                    if not have_keyframe:
                        if not data[1]:
                            return
                        have_keyframe = True
                    if accepted:
                        callback(data, frame_id)
                    elif (len(pending) < MAX_PENDING_FRAMES
                          and pending_bytes + len(data) <= MAX_PENDING_BYTES):
                        pending.append((data, frame_id))
                        pending_bytes += len(data)
                    else:
                        raise RuntimeError("AV1 startup frame queue overflow")
                except Exception as exc:
                    self._error = RuntimeError("AV1 frame delivery failed: " + str(exc))
                first_frame.set()

        try:
            self.capture.start_capture(deliver, settings)
            if not first_frame.wait(FIRST_FRAME_TIMEOUT):
                raise RuntimeError("AV1 encoder produced no key frame within 8 seconds")
            self.check_health()
            with self._lock:
                if self._error is not None:
                    raise self._error
                for data, frame_id in pending:
                    callback(data, frame_id)
                pending.clear()
                pending_bytes = 0
                accepted = True
            self.capture.request_idr_frame()
        except Exception:
            self.stop_capture()
            raise

    def stop_capture(self):
        with self._lock:
            self._stopped = True
        self.capture.stop_capture()

    def request_idr_frame(self):
        self.capture.request_idr_frame()
